describe('Search Result Race Conditions', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display only the latest search result when multiple requests are made concurrently', () => {
    // First search request
    cy.get('[data-testid="search-input"]').type('async programming');
    cy.get('[data-testid="search-button"]').click();

    // Wait for first search result to load
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('contain', 'Async Programming');

    // Second search request
    cy.get('[data-testid="search-input"]').type('async programming');
    cy.get('[data-testid="search-button"]').click();

    // Wait for second search result to load
    cy.get('[data-testid="search-results"]').should('be.visible');

    // Verify only the latest result is displayed
    cy.get('[data-testid="search-result-item"]').should('contain', 'Async Programming');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 1);
  });

  it('should handle race conditions gracefully when search input is cleared during a request', () => {
    // First search request
    cy.get('[data-testid="search-input"]').type('async programming');
    cy.get('[data-testid="search-button"]').click();

    // Wait for first search result to load
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('contain', 'Async Programming');

    // Clear search input
    cy.get('[data-testid="search-input"]').clear();

    // Second search request
    cy.get('[data-testid="search-input"]').type('async programming');
    cy.get('[data-testid="search-button"]').click();

    // Wait for second search result to load
    cy.get('[data-testid="search-results"]').should('be.visible');

    // Verify only the latest result is displayed
    cy.get('[data-testid="search-result-item"]').should('contain', 'Async Programming');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 1);
  });
});
